"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["7857"],{62333(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.modalidade_selecionada.natureza_legal_obrigatoria","status":422,"titulo":"Natureza legal da modalidade \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.selecao.modalidade_selecionada.natureza_legal_obrigatoria","requisitos":[],"oQueAconteceu":["Uma modalidade selecionada n\xe3o declarou `naturezaLegal`. A natureza legal\\ndescreve **o que** a modalidade \xe9 perante a lei (ampla concorr\xeancia, cota\\nreservada da Lei 12.711, entre outras) \u2014 \xe9 dela que depende, por exemplo, a\\nobrigatoriedade de seguir a cascata legal de remanejamento (ver\\n[`cota_reservada_exige_cascata`](/erros/uniplus.selecao.modalidade_selecionada.cota_reservada_exige_cascata)).\\nRoda antes das confer\xeancias de coer\xeancia de composi\xe7\xe3o e remanejamento \u2014 sem\\numa natureza legal declarada, n\xe3o h\xe1 como avaliar essas coer\xeancias.","**`naturezaLegal` n\xe3o vem do corpo do pedido da defini\xe7\xe3o de distribui\xe7\xe3o de\\nvagas** \u2014 \xe9 copiado do cadastro de modalidades de Configura\xe7\xe3o, no momento\\nem que a modalidade \xe9 selecionada (`IModalidadeReader`). O cadastro nunca\\ngrava uma modalidade sem esse campo \u2014 quando ele \xe9 omitido no cadastro, um\\nvalor padr\xe3o (`AMPLA`) \xe9 aplicado; n\xe3o existe modalidade cadastrada com\\nnatureza legal literalmente vazia. O que dispara este c\xf3digo, na pr\xe1tica, \xe9\\no token de natureza legal do cadastro **n\xe3o ser reconhecido** pelo\\nvocabul\xe1rio do m\xf3dulo Sele\xe7\xe3o \u2014 hoje os dois vocabul\xe1rios coincidem, ent\xe3o\\no cen\xe1rio real \xe9 uma diverg\xeancia futura entre eles (o cadastro evoluindo\\nantes deste m\xf3dulo), n\xe3o um dado corrompido.","N\xe3o acumula com nenhuma outra viola\xe7\xe3o \u2014 \xe9 a primeira que falhar que\\ninterrompe a cria\xe7\xe3o da modalidade.","Este c\xf3digo tamb\xe9m aparece na **retifica\xe7\xe3o em ato \xfanico**: antes de\\ncongelar a vers\xe3o nova, o sistema l\xea as vers\xf5es j\xe1 publicadas do processo,\\ne essa leitura recria cada modalidade selecionada a partir do que foi\\ncongelado \u2014 a mesma confer\xeancia roda de novo, sozinha."],"comoResolver":["O campo n\xe3o est\xe1 no corpo do pedido que voc\xea enviou \u2014 est\xe1 na modalidade cadastrada\\nem Configura\xe7\xe3o. Confira l\xe1 a natureza legal cadastrada; se ela parecer\\ncorreta e o erro persistir, \xe9 sinal de que o token que o cadastro emite n\xe3o\\n\xe9 mais reconhecido pelo m\xf3dulo Sele\xe7\xe3o \u2014 um problema de sincroniza\xe7\xe3o entre\\nos dois vocabul\xe1rios, n\xe3o de dado ausente.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o problema n\xe3o est\xe1 no que\\nfoi enviado agora \u2014 est\xe1 em uma vers\xe3o j\xe1 publicada. Isso indica uma\\ninconsist\xeancia nessa vers\xe3o; abra uma investiga\xe7\xe3o em vez de tentar\\ncorrigir pelo envio."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Modalidade selecionada"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);